import { ComponentProps } from 'react';

import { ColumnDefsConfig, Table } from 'components';
import { TableDataType } from 'components/Table/types';

import { tableConfig } from './config';
import { StyledKpiDrillDownTable } from './KpiDrillDownTable.styles';

type BaseTableProps = ComponentProps<typeof Table>;

interface KpiDrillDownTableProps {
  dataTestId?: string;
  data: TableDataType;
  config?: ColumnDefsConfig;
  tableStyle?: BaseTableProps['style'];
  rowHeight?: BaseTableProps['rowHeight'];
  headerHeight?: BaseTableProps['headerHeight'];
  groupHeaderHeight?: BaseTableProps['groupHeaderHeight'];
  scrollbarWidth?: BaseTableProps['scrollbarWidth'];
  fixedHeight?: BaseTableProps['fixedHeight'];
  autoHeight?: BaseTableProps['autoHeight'];
  manageColumnWidths?: BaseTableProps['manageColumnWidths'];
}

export const KpiDrillDownTable = ({
  dataTestId,
  data,
  config,
  tableStyle,
  rowHeight = 42,
  headerHeight = 44,
  groupHeaderHeight = 56,
  scrollbarWidth = 8,
  fixedHeight,
  autoHeight,
  manageColumnWidths,
}: KpiDrillDownTableProps) => {
  return (
    <StyledKpiDrillDownTable>
      <Table
        dataTestId={
          dataTestId ? `${dataTestId}-kpi-drill-down-table` : undefined
        }
        data={data}
        rowHeight={rowHeight}
        headerHeight={headerHeight}
        groupHeaderHeight={groupHeaderHeight}
        scrollbarWidth={scrollbarWidth}
        fixedHeight={fixedHeight}
        autoHeight={autoHeight}
        manageColumnWidths={manageColumnWidths}
        getRowHeight={() => rowHeight ?? 52}
        columnDefsConfig={{ ...tableConfig, ...config }}
        style={tableStyle}
      />
    </StyledKpiDrillDownTable>
  );
};
